/** A seeded wish's words in the visitor's language, or null for a wish a visitor wrote. */
export function seededWish(title: string, lang: Lang): WishWords | null {
  return lang === "en" ? null : (WISH_SEED[title]?.[lang] ?? null);
}

/** A tag in the visitor's language. */
export function wishTag(tag: string, lang: Lang): string {
  return lang === "en" ? tag : (WISH_TAGS[tag]?.[lang] ?? tag);
}
